"""Returns product of two nD vectors
    (same as itemwise multiplication)"""
def mulND(v1: Any, v2: Any) -> object {
    return [(vv1 * vv2) for (vv1, vv2) in zip(v1, v2)];
}

"""
    Pick requested key value pairs from a dictionary and return a new dictionary
    """
def pick_attributes(
    old_dict: Any, attributes: Any, skip_non_existing: Any = True
) -> object {
    new_dict = {};
    for attribute in attributes {
        if (attribute in old_dict) {
            new_dict[attribute] = old_dict[attribute];
        } elif not skip_non_existing {
            new_dict[attribute] = None;
        }
    }
    return new_dict;
}

